43. /**
44.  * A NodeProxy Proxy which enhances NodeProxy
45.  * with a W3C DOM implementation by proxying to
46.  * its underlying typed node which is available
47.  * through NodeProxy.getNode()
48.  *
49.  * @author <a href="mailto:adam.retter@googlemail.com">Adam Retter</a>
50.  */
51. class DomEnhancingNodeProxyAdapter {
52.     
53.     public static NodeProxy create(final NodeProxy nodeProxy) {
54.         
55.         final Class<? extends Node> clazzes[] = getNodeClasses(nodeProxy);
56.          
57.         // NoOp Callback is for NodeProxy calls
58.         // NodeDispatched Callback is for the underlying Node calls
59.         final Callback[] callbacks = {
60.           NoOp.INSTANCE,
61.           new NodeDispatcher(nodeProxy)
62.         };
63.         
64.         final CallbackFilter callbackFilter = method -> {
65. 
66.             final Class declaringClass = method.getDeclaringClass();
67. 
68.             //look for nodes
69.             boolean isMethodOnNode = false;
70.             if(declaringClass.equals(Node.class)) {
71.                 isMethodOnNode = true;
72.             } else {
73.                 //search parent interfaces
74.                 for(final Class iface : declaringClass.getInterfaces()) {
75.                     if(iface.equals(Node.class)) {
76.                         isMethodOnNode = true;
77.                         break;
78.                     }
79.                 }
80.             }
81. 
82.             if(isMethodOnNode) {
83.                 return 1; //The NodeDispatcher
84.             } else {
85.                 return 0; //The NoOp pass through
86.             }
87.         };
88.         
89.         final Enhancer enhancer = new Enhancer();
90.         enhancer.setSuperclass(NodeProxy.class);
91.         enhancer.setInterfaces(clazzes);
92.         enhancer.setCallbackFilter(callbackFilter);
93.         enhancer.setCallbacks(callbacks);
94.         
95.         return (NodeProxy)enhancer.create(
96.             new Class[] {
97.                 NodeHandle.class
98.             },
99.             new Object[] {
100.                 nodeProxy
101.             });
102.     }
103.     
104.     private static Class<? extends Node>[] getNodeClasses(final NodeProxy nodeProxy) {
105.         switch(nodeProxy.getType()) {
106.             
107.             case Type.DOCUMENT:
108.                 return new Class[] {
109.                     Document.class,
110.                     Node.class
111.                 };
112.             
113.             case Type.ELEMENT:
114.                 return new Class[] {
115.                     Element.class,
116.                     Node.class
117.                 };
118. 
119.             case Type.ATTRIBUTE:
120.                 return new Class[] {
121.                     Attr.class,
122.                     Node.class
123.                 };
124.                 
125.             case Type.TEXT:
126.                 return new Class[] {
127.                     Text.class,
128.                     Node.class
129.                 };
130. 
131.             default:
132.                 return new Class[] {
133.                     Node.class
134.                 };
135.         }
136.     }
137.     
138.     public static class NodeDispatcher implements Dispatcher {
139.         
140.         private final NodeProxy nodeProxy;
141.         
142.         public NodeDispatcher(final NodeProxy nodeProxy) {
143.             this.nodeProxy = nodeProxy;
144.         }
145.         
146.         @Override
147.         public Object loadObject() throws Exception {
148.             return nodeProxy.getNode();
149.         }
150.     }
151. }

